
// PyLab kernel worker — AUTO-GENERATED by scripts/build_worker.py (do not edit).
// Runs real CPython (Pyodide/WebAssembly) with the exact same exercise-grading
// harness that validated every exercise offline (scripts/py_harness.py).

const PYODIDE_VERSION = "v0.27.5";
const CDN = "https://cdn.jsdelivr.net/pyodide/" + PYODIDE_VERSION + "/full/";

const KERNEL_PY = "#!/usr/bin/env python3\n\"\"\"py_harness.py \u2014 the single source of truth for exercise grading.\n\nRuns identically inside Pyodide (browser kernel) and CPython (offline validator).\nEntry point: run_exercise_json(user_code, exercise_json) -> JSON string.\n\nTest kinds:\n  exact    \u2014 actual == expected (numbers, str, list, dict, tuple, bool, None)\n  float    \u2014 math.isclose recursively through lists/tuples (rel 1e-6, abs 1e-9)\n  array    \u2014 numeric numpy arrays: shape equal + np.allclose(equal_nan=True)\n  frame    \u2014 pandas DataFrame via assert_frame_equal(check_dtype=False)\n  series   \u2014 pandas Series via assert_series_equal(check_dtype=False, check_names=False)\n  set      \u2014 unordered set equality\n  raises   \u2014 expr must raise; expected is the exception class name (e.g. \"ValueError\")\n  stdout   \u2014 program-style: user code re-run with fed stdin, stdout compared (normalized)\n\nEach test: {name, kind, hidden, weight?, setup?, expr?, expected?, stdin?, explain?}\n  - setup:    python statements run before evaluation (build test data)\n  - expected: SELF-CONTAINED python expression (never references setup variables)\n  - expr:     python expression producing the actual value (usually calls solve(...))\n\"\"\"\nimport sys, io, json, math, time, traceback\n\n\ndef _fmt(v, limit=400):\n    try:\n        s = repr(v)\n    except Exception:\n        s = \"<unreprable %s>\" % type(v).__name__\n    if len(s) > limit:\n        s = s[:limit] + \" \u2026 (%d chars total)\" % len(s)\n    return s\n\n\ndef _isclose(a, b, rel=1e-6, abs_=1e-9):\n    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):\n        return len(a) == len(b) and all(_isclose(x, y, rel, abs_) for x, y in zip(a, b))\n    if isinstance(a, bool) or isinstance(b, bool):\n        return a == b\n    if isinstance(a, (int, float)) and isinstance(b, (int, float)):\n        return math.isclose(a, b, rel_tol=rel, abs_tol=abs_)\n    return a == b\n\n\ndef _normalize_stdout(s):\n    lines = [ln.rstrip() for ln in s.replace(\"\\r\\n\", \"\\n\").split(\"\\n\")]\n    while lines and lines[-1] == \"\":\n        lines.pop()\n    return \"\\n\".join(lines)\n\n\ndef _compare(kind, actual, expected):\n    \"\"\"Return (ok, message).\"\"\"\n    if kind == \"exact\":\n        ok = actual == expected\n        return ok, \"\" if ok else \"got %s \u00b7 expected %s\" % (_fmt(actual), _fmt(expected))\n    if kind == \"float\":\n        ok = _isclose(actual, expected)\n        return ok, \"\" if ok else \"got %s \u00b7 expected \u2248 %s\" % (_fmt(actual), _fmt(expected))\n    if kind == \"array\":\n        import numpy as np\n        a, e = np.asarray(actual), np.asarray(expected)\n        if a.shape != e.shape:\n            return False, \"shape %s does not match expected %s\" % (a.shape, e.shape)\n        ok = bool(np.allclose(a, e, equal_nan=True, rtol=1e-6, atol=1e-9))\n        return ok, \"\" if ok else \"got %s \u00b7 expected %s\" % (a.tolist(), e.tolist())\n    if kind == \"frame\":\n        import pandas as pd\n        try:\n            pd.testing.assert_frame_equal(actual, expected, check_dtype=False)\n            return True, \"\"\n        except AssertionError as ex:\n            first = \"\\n\".join(str(ex).strip().split(\"\\n\")[:2])\n            return False, first[:300]\n    if kind == \"series\":\n        import pandas as pd\n        try:\n            pd.testing.assert_series_equal(actual, expected, check_dtype=False, check_names=False)\n            return True, \"\"\n        except AssertionError as ex:\n            first = \"\\n\".join(str(ex).strip().split(\"\\n\")[:2])\n            return False, first[:300]\n    if kind == \"set\":\n        try:\n            sa, se = set(actual), set(expected)\n            ok = sa == se\n        except TypeError:\n            return False, \"values are not hashable \u2014 cannot compare as a set\"\n        if ok:\n            return True, \"\"\n        return False, \"got %s \u00b7 expected %s\" % (\n            sorted(map(repr, sa))[:12], sorted(map(repr, se))[:12])\n    raise ValueError(\"unknown comparison kind: %r\" % kind)\n\n\ndef run_exercise_json(user_code, exercise_json):\n    \"\"\"Grade `user_code` against an exercise spec. Returns a JSON string.\"\"\"\n    try:\n        ex = json.loads(exercise_json)\n    except Exception:\n        return json.dumps({\"status\": \"harness-error\", \"message\": \"exercise spec is not valid JSON\"})\n\n    t0 = time.perf_counter()\n    BUDGET_SECONDS = 12.0\n    tests = ex.get(\"tests\", [])\n    bootstrap = ex.get(\"bootstrap\", \"\")\n\n    def bail(status, user_error, stdout=\"\"):\n        return json.dumps({\n            \"status\": status, \"results\": [], \"stdout\": (stdout or \"\")[:4000],\n            \"passed\": 0, \"total\": len(tests), \"userError\": user_error,\n            \"timeMs\": int((time.perf_counter() - t0) * 1000),\n        })\n\n    # \u2500\u2500 1) Compile once \u2014 syntax errors are caught without executing \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    try:\n        code_obj = compile(user_code, \"<student>\", \"exec\")\n    except SyntaxError:\n        return bail(\"syntax-error\", traceback.format_exc(limit=3))\n    except Exception:\n        return bail(\"syntax-error\", traceback.format_exc(limit=3))\n\n    ns = {}\n    if bootstrap:\n        try:\n            exec(compile(bootstrap, \"<bootstrap>\", \"exec\"), ns)\n        except Exception:\n            return bail(\"harness-error\", \"bootstrap failed:\\n\" + traceback.format_exc(limit=2))\n\n    needs_solve = any(t.get(\"kind\") != \"stdout\" for t in tests)\n    if needs_solve:\n        cap = io.StringIO()\n        old_stdout = sys.stdout\n        sys.stdout = cap\n        try:\n            exec(code_obj, ns)\n        except SyntaxError:\n            return bail(\"syntax-error\", traceback.format_exc(limit=3), cap.getvalue())\n        except Exception:\n            return bail(\"runtime-error\", traceback.format_exc(limit=3), cap.getvalue())\n        finally:\n            sys.stdout = old_stdout\n        user_stdout = cap.getvalue()\n        if not callable(ns.get(\"solve\")):\n            return bail(\"error\", \"NameError: your code must define a function named `solve`\", user_stdout)\n    else:\n        # program-style exercise: code runs per test with fed stdin, never here\n        user_stdout = \"\"\n\n    # \u2500\u2500 2) Run each test in an isolated copy of the namespace \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n    results = []\n    for t in tests:\n        if time.perf_counter() - t0 > BUDGET_SECONDS:\n            results.append({\n                \"name\": t.get(\"name\", \"?\"), \"hidden\": bool(t.get(\"hidden\", False)),\n                \"kind\": t.get(\"kind\", \"exact\"), \"passed\": False,\n                \"message\": \"Time budget exceeded \u2014 check for infinite loops.\",\n                \"expected\": \"\", \"actual\": \"\", \"explain\": t.get(\"explain\", \"\"), \"status\": \"timeout\",\n            })\n            continue\n        r = {\n            \"name\": t.get(\"name\", \"?\"), \"hidden\": bool(t.get(\"hidden\", False)),\n            \"kind\": t.get(\"kind\", \"exact\"), \"passed\": False, \"message\": \"\",\n            \"expected\": \"\", \"actual\": \"\", \"explain\": t.get(\"explain\", \"\"), \"status\": \"done\",\n        }\n        tns = dict(ns)\n        try:\n            kind = t[\"kind\"]\n            if kind == \"stdout\":\n                sio = io.StringIO()\n                old_in, old_out = sys.stdin, sys.stdout\n                sys.stdin = io.StringIO(t.get(\"stdin\", \"\"))\n                sys.stdout = sio\n                try:\n                    ns2 = {}\n                    if bootstrap:\n                        exec(compile(bootstrap, \"<bootstrap>\", \"exec\"), ns2)\n                    exec(code_obj, ns2)\n                finally:\n                    sys.stdin, sys.stdout = old_in, old_out\n                actual = _normalize_stdout(sio.getvalue())\n                expected = _normalize_stdout(str(t.get(\"expected\", \"\")))\n                r[\"passed\"] = actual == expected\n                r[\"actual\"], r[\"expected\"] = actual, expected\n                if not r[\"passed\"]:\n                    r[\"message\"] = \"printed output does not match (trailing blank lines are ignored)\"\n            elif kind == \"raises\":\n                if t.get(\"setup\"):\n                    exec(compile(t[\"setup\"], \"<setup>\", \"exec\"), tns)\n                raised = None\n                try:\n                    eval(t[\"expr\"], tns)  # noqa: S307\n                except Exception as ex_:\n                    raised = type(ex_).__name__\n                expected_name = str(t.get(\"expected\", \"Exception\"))\n                r[\"passed\"] = raised == expected_name\n                r[\"actual\"], r[\"expected\"] = raised or \"no exception\", expected_name\n                if not r[\"passed\"]:\n                    r[\"message\"] = \"expected %s to be raised, got %s\" % (\n                        expected_name, raised or \"no exception\")\n            else:\n                if t.get(\"setup\"):\n                    exec(compile(t[\"setup\"], \"<setup>\", \"exec\"), tns)\n                # expected FIRST \u2014 immune to in-place mutation by user code\n                expected = eval(t[\"expected\"], tns)  # noqa: S307\n                actual = eval(t[\"expr\"], tns)        # noqa: S307\n                ok, msg = _compare(kind, actual, expected)\n                r[\"passed\"] = ok\n                r[\"message\"] = msg\n                r[\"actual\"], r[\"expected\"] = _fmt(actual), _fmt(expected)\n        except Exception:\n            r[\"passed\"] = False\n            r[\"status\"] = \"error\"\n            r[\"message\"] = traceback.format_exc(limit=2).strip()[-300:]\n        finally:\n            # prevent figure state leaking between tests (matplotlib/seaborn)\n            try:\n                if \"matplotlib.pyplot\" in sys.modules:\n                    sys.modules[\"matplotlib.pyplot\"].close(\"all\")\n            except Exception:\n                pass\n        results.append(r)\n\n    passed = sum(1 for r in results if r[\"passed\"])\n    total = len(results)\n    status = \"passed\" if total and passed == total else \"failed\"\n    return json.dumps({\n        \"status\": status, \"results\": results, \"stdout\": user_stdout[:4000],\n        \"passed\": passed, \"total\": total,\n        \"timeMs\": int((time.perf_counter() - t0) * 1000),\n    })\n\n# \u2500\u2500\u2500 PyLab notebook kernel (browser only) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nimport sys, io, json, ast, base64, time as _time\n\n_KERNEL_NS = {\"__name__\": \"__main__\"}\n\n\ndef _fig_to_png(fig):\n    buf = io.BytesIO()\n    fig.savefig(buf, format=\"png\", dpi=110, bbox_inches=\"tight\")\n    return \"data:image/png;base64,\" + base64.b64encode(buf.getvalue()).decode()\n\n\n_MPL_CAPTURED = []   # figures snapshotted at close() time (repo examples close their figs)\n_MPL_READY = False\n\n\ndef _pylab_prepare_matplotlib():\n    \"\"\"Pre-import matplotlib (Agg) and snapshot figures when code closes them.\n    Called by the worker after the matplotlib/seaborn package is loaded; the\n    cell's own `import matplotlib.pyplot` then binds to this patched module.\"\"\"\n    global _MPL_READY\n    if _MPL_READY:\n        return\n    try:\n        import matplotlib\n        matplotlib.use(\"Agg\")\n        import matplotlib.figure\n        import matplotlib.pyplot as plt\n        orig_close = plt.close\n\n        def _capture_and_close(target=None):\n            try:\n                if target is None or target == \"all\":\n                    for num in plt.get_fignums():\n                        _MPL_CAPTURED.append(_fig_to_png(plt.figure(num)))\n                elif isinstance(target, matplotlib.figure.Figure):\n                    _MPL_CAPTURED.append(_fig_to_png(target))\n                else:\n                    _MPL_CAPTURED.append(_fig_to_png(plt.figure(target)))\n            except Exception:\n                pass\n            finally:\n                orig_close(target)\n\n        plt.close = _capture_and_close\n        _MPL_READY = True\n    except Exception:\n        pass\n\n\ndef _pylab_run_cell(code):\n    global _MPL_CAPTURED\n    _MPL_CAPTURED = []\n    t0 = _time.perf_counter()\n    out = io.StringIO()\n    old_out, old_err = sys.stdout, sys.stderr\n    sys.stdout = out\n    sys.stderr = out\n    result_repr = None\n    error = None\n    error_line = None\n    try:\n        tree = ast.parse(code, \"<cell>\")\n        last = tree.body[-1] if tree.body else None\n        if isinstance(last, ast.Expr):\n            if len(tree.body) > 1:\n                body_mod = ast.Module(body=tree.body[:-1], type_ignores=[])\n                exec(compile(body_mod, \"<cell>\", \"exec\"), _KERNEL_NS)\n            val = eval(compile(ast.Expression(last.value), \"<cell>\", \"eval\"), _KERNEL_NS)\n            _KERNEL_NS[\"_\"] = val\n            try:\n                result_repr = repr(val)\n            except Exception:\n                result_repr = \"<%s object>\" % type(val).__name__\n        else:\n            exec(compile(tree, \"<cell>\", \"exec\"), _KERNEL_NS)\n    except SyntaxError as e:\n        error = traceback.format_exc(limit=1)\n        error_line = e.lineno\n    except Exception:\n        error = traceback.format_exc(limit=3)\n        try:\n            tb = sys.exc_info()[2]\n            while tb.tb_next is not None:\n                tb = tb.tb_next\n            error_line = tb.tb_lineno\n        except Exception:\n            pass\n    finally:\n        sys.stdout = old_out\n        sys.stderr = old_err\n    images = list(_MPL_CAPTURED)\n    plt = sys.modules.get(\"matplotlib.pyplot\")\n    if plt is not None and hasattr(plt, \"get_fignums\"):\n        for num in plt.get_fignums():\n            try:\n                images.append(_fig_to_png(plt.figure(num)))\n            except Exception:\n                pass\n        try:\n            plt.close(\"all\")\n        except Exception:\n            pass\n    return json.dumps(\n        {\n            \"ok\": error is None,\n            \"stdout\": out.getvalue(),\n            \"resultRepr\": result_repr,\n            \"hasResult\": result_repr is not None,\n            \"error\": error,\n            \"errorLine\": error_line,\n            \"images\": images,\n            \"timeMs\": int((_time.perf_counter() - t0) * 1000),\n        }\n    )\n\n\ndef _pylab_reset():\n    _KERNEL_NS.clear()\n    _KERNEL_NS[\"__name__\"] = \"__main__\"\n\n\ndef _pylab_run_tests(user_code, exercise_json):\n    try:\n        r = run_exercise_json(user_code, exercise_json)\n    except Exception:\n        r = json.dumps(\n            {\n                \"status\": \"harness-error\",\n                \"results\": [],\n                \"stdout\": \"\",\n                \"passed\": 0,\n                \"total\": 0,\n                \"userError\": traceback.format_exc(limit=2),\n                \"timeMs\": 0,\n            }\n        )\n    plt = sys.modules.get(\"matplotlib.pyplot\")\n    if plt is not None and hasattr(plt, \"get_fignums\"):\n        try:\n            plt.close(\"all\")\n        except Exception:\n            pass\n    return r\n";

let pyodide = null;
let booted = false;

function post(msg) {
  self.postMessage(msg);
}

async function boot() {
  post({ id: "kernel", type: "status", status: "booting" });
  importScripts(CDN + "pyodide.js");
  pyodide = await loadPyodide({ indexURL: CDN });
  pyodide.runPython(KERNEL_PY);
  booted = true;
  const info = pyodide.runPython(
    "import sys; '%d.%d.%d' % sys.version_info[:3]"
  );
  post({
    id: "kernel",
    type: "status",
    status: "ready",
    detail: "Python " + info + " · Pyodide " + pyodide.version,
  });
}

async function ensureBoot() {
  if (!booted) await boot();
}

async function loadPackages(packages) {
  let mplLoaded = false;
  for (const pkg of packages) {
    try {
      if (pkg.startsWith("micropip:")) {
        const name = pkg.slice("micropip:".length);
        post({ id: "kernel", type: "pkg-progress", package: name, done: false });
        await pyodide.loadPackage("micropip");
        const micropip = pyodide.pyimport("micropip");
        await micropip.install(name);
        micropip.destroy();
        if (name === "seaborn") mplLoaded = true;
      } else {
        post({ id: "kernel", type: "pkg-progress", package: pkg, done: false });
        await pyodide.loadPackage(pkg);
        if (pkg === "matplotlib") mplLoaded = true;
      }
      post({ id: "kernel", type: "pkg-progress", package: pkg, done: true });
    } catch (e) {
      post({
        id: "kernel",
        type: "pkg-progress",
        package: pkg,
        done: true,
        error: String(e),
      });
    }
  }
  if (mplLoaded) {
    try {
      pyodide.runPython("_pylab_prepare_matplotlib()");
    } catch (e) {
      console.warn("[kernel] matplotlib prepare failed", e);
    }
  }
}

async function handleRun(msg) {
  await ensureBoot();
  const fn = pyodide.globals.get("_pylab_run_cell");
  let payload;
  try {
    payload = fn(msg.code);
  } finally {
    fn.destroy();
  }
  let parsed;
  try {
    parsed = JSON.parse(payload);
  } catch (e) {
    parsed = {
      ok: false,
      stdout: "",
      hasResult: false,
      error: "Kernel returned an unreadable result: " + String(e),
      images: [],
      timeMs: 0,
    };
  }
  post({ id: msg.id, type: "run-result", payload: parsed });
}

async function handleTest(msg) {
  await ensureBoot();
  const fn = pyodide.globals.get("_pylab_run_tests");
  let payload;
  try {
    payload = fn(msg.userCode, JSON.stringify(msg.exercise));
  } finally {
    fn.destroy();
  }
  let parsed;
  try {
    parsed = JSON.parse(payload);
  } catch (e) {
    parsed = {
      status: "harness-error",
      results: [],
      stdout: "",
      passed: 0,
      total: 0,
      userError: String(e),
      timeMs: 0,
    };
  }
  post({ id: msg.id, type: "test-result", payload: parsed });
}

self.onmessage = async (event) => {
  const msg = event.data;
  try {
    switch (msg.type) {
      case "init":
        await boot();
        break;
      case "loadPackages":
        await ensureBoot();
        post({ id: "kernel", type: "status", status: "loading-pkg", detail: msg.packages.join(", ") });
        await loadPackages(msg.packages);
        post({ id: "kernel", type: "status", status: "ready" });
        break;
      case "run":
        await handleRun(msg);
        break;
      case "test":
        await handleTest(msg);
        break;
      case "reset":
        await ensureBoot();
        pyodide.runPython("_pylab_reset()");
        post({ id: "kernel", type: "status", status: "ready", detail: "kernel memory cleared" });
        break;
      default:
        post({ id: msg.id, type: "error", message: "unknown message type" });
    }
  } catch (e) {
    post({ id: msg.id || "kernel", type: "error", message: String(e && e.message ? e.message : e) });
  }
};
